import SnackBar from "@/components/SnackBar.vue";
import { create_list_update_org_prefix } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "PrefixManagement",
  components: {
    SnackBar
  },
  data() {
    return {
      windowHeight: window.innerHeight - 260,
      loading: false,
      isFormValid: false,
      SnackBarComponent: {},
      prefixes: {
        CUSTOMER: [],
        VENDOR: [],
        QUOTATION: [],
        SALES_ORDER: [],
        SALE: [],
        PROFORMA: [],
        PAYMENT_IN: [],
        PAYMENT_OUT: [],
        MEMBER: [],
        PROJECT: [],
        PURCHASE: [],
        PURCHASE_ORDER: []
      },
      selectedPrefixes: {
        CUSTOMER: null,
        PROJECT: null,
        VENDOR: null,
        QUOTATION: null,
        MEMBER: null,
        SALES_ORDER: null,
        SALE: null,
        PROFORMA: null,
        PAYMENT_IN: null,
        PAYMENT_OUT: null,
        PURCHASE: null,
        PURCHASE_ORDER: null
      },
      newPrefixes: {
        CUSTOMER: "",
        PROJECT: "",
        VENDOR: "",
        QUOTATION: "",
        MEMBER: "",
        SALES_ORDER: "",
        SALE: "",
        PROFORMA: "",
        PAYMENT_IN: "",
        PAYMENT_OUT: "",
        PURCHASE: "",
        PURCHASE_ORDER: ""
      },
      showAddNew: {
        CUSTOMER: false,
        PROJECT: false,
        VENDOR: false,
        QUOTATION: false,
        MEMBER: false,
        SALES_ORDER: false,
        SALE: false,
        PROFORMA: false,
        PAYMENT_IN: false,
        PAYMENT_OUT: false,
        PURCHASE: false,
        PURCHASE_ORDER: false
      }
    };
  },
  async created() {
    await this.GetPrefixes();
  },
  methods: {
    async GetPrefixes() {
      try {
        this.loading = true;
        const response = await API.graphql(graphqlOperation(create_list_update_org_prefix, {
          input: {
            action_type: "LIST"
          }
        }));
        let result = JSON.parse(response.data.create_list_update_org_prefix);
        // console.log("API Response:", result);

        if (result.Status === "SUCCESS" && result.data) {
          // Clear existing data first to prevent duplicates
          this.prefixes = {
            CUSTOMER: [],
            PROJECT: [],
            VENDOR: [],
            QUOTATION: [],
            MEMBER: [],
            SALES_ORDER: [],
            SALE: [],
            PROFORMA: [],
            PAYMENT_IN: [],
            PAYMENT_OUT: [],
            PURCHASE: [],
            PURCHASE_ORDER: []
          };

          // Transform API data to match our component structure
          this.prefixes = {
            CUSTOMER: result.data.CUSTOMER || [],
            PROJECT: result.data.PROJECT || [],
            VENDOR: result.data.VENDOR || [],
            QUOTATION: result.data.QUOTATION || [],
            MEMBER: result.data.MEMBER || [],
            SALES_ORDER: result.data.SALES_ORDER || [],
            SALE: result.data.SALE || [],
            PROFORMA: result.data.PROFORMA || [],
            PAYMENT_IN: result.data.PAYMENT_IN || [],
            PAYMENT_OUT: result.data.PAYMENT_OUT || [],
            PURCHASE: result.data.PURCHASE || [],
            PURCHASE_ORDER: result.data.PURCHASE_ORDER || []
          };
          this.updateSelectedPrefixes();
          // this.showSnackBar('Prefixes loaded successfully', 'success');
        }
        //  else {
        // this.showSnackBar("Failed to load prefixes", "error");
        // }
      } catch (error) {
        console.error("Error fetching prefixes:", error);
        this.showSnackBar("Error loading prefixes", "error");
      } finally {
        this.loading = false;
      }
    },
    updateSelectedPrefixes() {
      Object.keys(this.prefixes).forEach(type => {
        if (this.prefixes[type] && Array.isArray(this.prefixes[type])) {
          const activePrefix = this.prefixes[type].find(prefix => prefix.is_default === true);
          this.selectedPrefixes[type] = activePrefix ? activePrefix.prefix_name : null;
        } else {
          this.selectedPrefixes[type] = null;
        }
      });
    },
    getCurrentPrefix(type) {
      if (this.prefixes[type] && Array.isArray(this.prefixes[type]) && this.prefixes[type].length > 0) {
        const activePrefix = this.prefixes[type].find(prefix => prefix.is_default === true);
        return activePrefix ? activePrefix.prefix_name : null;
      }
      return null;
    },
    getPrefixOptions(type) {
      if (!this.prefixes[type] || !Array.isArray(this.prefixes[type])) return [];
      return this.prefixes[type].map(prefix => ({
        label: `${prefix.prefix_name}${prefix.is_default ? " (Active)" : ""}`,
        value: prefix.prefix_name,
        is_default: prefix.is_default,
        prefix_id: prefix.prefix_id,
        prefix_type: prefix.prefix_type,
        prefix_status: prefix.prefix_status,
        created_on: prefix.created_on
      }));
    },
    async onPrefixSelect(type) {
      if (!this.selectedPrefixes[type]) return;

      // Ensure prefixes[type] exists and is an array
      if (!this.prefixes[type] || !Array.isArray(this.prefixes[type])) {
        this.prefixes[type] = [];
        return;
      }

      // Set all prefixes to inactive
      try {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        const response = await API.graphql(graphqlOperation(create_list_update_org_prefix, {
          input: {
            action_type: "EDIT",
            prefix_type: type,
            // prefix_name: this.selectedPrefixes[type],
            prefix_id: this.prefixes[type].find(prefix => prefix.prefix_name === this.selectedPrefixes[type]).prefix_id,
            organization_id: data.organization.organization_id,
            is_default: true
          }
        }));
        let result = JSON.parse(response.data.create_list_update_org_prefix);
        // console.log("API Response:", result);

        if (result.Status === "SUCCESS") {
          // Clear the input and hide add section first
          this.newPrefixes[type] = "";
          this.showAddNew[type] = false;
          this.showSnackBar(`${type} prefix activated successfully`, "success");

          // Add a small delay before refreshing to ensure the API has processed the change
          setTimeout(() => {
            this.GetPrefixes();
          }, 500);
        } else {
          this.showSnackBar("Failed to activate prefix", "error");
        }
      } catch (error) {
        console.error("Error activating prefix:", error);
        this.showSnackBar("Error activating prefix", "error");
      } finally {
        this.loading = false;
      }
    },
    async addNewPrefix(type) {
      if (!this.newPrefixes[type] || this.newPrefixes[type].trim() === "") {
        return;
      }

      // Ensure prefixes[type] exists and is an array
      if (!this.prefixes[type] || !Array.isArray(this.prefixes[type])) {
        this.prefixes[type] = [];
      }

      // Check if prefix already exists
      const exists = this.prefixes[type].some(prefix => prefix.prefix_name.toLowerCase() === this.newPrefixes[type].toLowerCase());
      if (exists) {
        this.showSnackBar(`${type} prefix already exists`, "warning");
        return;
      }
      try {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        const response = await API.graphql(graphqlOperation(create_list_update_org_prefix, {
          input: {
            action_type: "CREATE",
            prefix_type: type,
            prefix_name: this.newPrefixes[type],
            organization_id: data.organization.organization_id,
            is_default: true
          }
        }));
        let result = JSON.parse(response.data.create_list_update_org_prefix);
        // console.log("API Response:", result);

        if (result.Status === "SUCCESS") {
          // Clear the input and hide add section first
          this.newPrefixes[type] = "";
          this.showAddNew[type] = false;
          this.showSnackBar(`New ${type} prefix added successfully`, "success");

          // Add a small delay before refreshing to ensure the API has processed the change
          setTimeout(() => {
            this.GetPrefixes();
          }, 500);
        } else {
          this.showSnackBar("Failed to create prefix", "error");
        }
      } catch (error) {
        console.error("Error creating prefix:", error);
        this.showSnackBar("Error creating prefix", "error");
      } finally {
        this.loading = false;
      }
    },
    formatDate(timestamp) {
      if (!timestamp) return "";
      const date = new Date(timestamp * 1000); // Convert Unix timestamp to Date
      return date.toLocaleDateString() + " " + date.toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit"
      });
    },
    async savePrefixes() {
      this.loading = true;
      try {
        // Here you would typically call the API to save the prefixes
        // For now, we'll just show a success message
        this.showSnackBar("Prefixes saved successfully!", "success");
      } catch (error) {
        console.error("Error saving prefixes:", error);
        this.showSnackBar("Error saving prefixes", "error");
      } finally {
        this.loading = false;
      }
    },
    resetToDefaults() {
      // Reset to API defaults
      this.GetPrefixes();
      this.newPrefixes = {
        CUSTOMER: "",
        PROJECT: "",
        VENDOR: "",
        QUOTATION: "",
        MEMBER: "",
        SALES_ORDER: "",
        SALE: "",
        PROFORMA: "",
        PAYMENT_IN: "",
        PAYMENT_OUT: "",
        PURCHASE: "",
        PURCHASE_ORDER: ""
      };
      this.showAddNew = {
        CUSTOMER: false,
        PROJECT: false,
        VENDOR: false,
        QUOTATION: false,
        MEMBER: false,
        SALES_ORDER: false,
        SALE: false,
        PROFORMA: false,
        PAYMENT_IN: false,
        PAYMENT_OUT: false,
        PURCHASE: false,
        PURCHASE_ORDER: false
      };
      this.showSnackBar("Prefixes reset to defaults", "info");
    },
    showSnackBar(message, color = "success") {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: color,
        SnackbarText: message,
        timeout: 3000,
        Top: true
      };
    }
  }
};
